import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:intl/intl.dart';import '../../../core/providers/app_providers.dart';import '../../../core/domain/extended_entities.dart';
class FeedingScreen extends ConsumerStatefulWidget{const FeedingScreen({super.key});@override ConsumerState<FeedingScreen> createState()=>_FeedingScreenState();}
class _FeedingScreenState extends ConsumerState<FeedingScreen>{final food=TextEditingController(),amount=TextEditingController(),note=TextEditingController();String meal='Meal',unit='cup';@override void dispose(){food.dispose();amount.dispose();note.dispose();super.dispose();}
Future<void> add()async{final p=ref.read(appControllerProvider).selectedPet;if(p==null||food.text.trim().isEmpty)return;final e=FeedingEntry(id:DateTime.now().microsecondsSinceEpoch.toString(),petId:p.id,at:DateTime.now(),food:food.text.trim(),amount:double.tryParse(amount.text),unit:unit,mealType:meal,note:note.text.trim());await ref.read(appControllerProvider).save('feeding_entries',e.toMap());food.clear();amount.clear();note.clear();}
@override Widget build(BuildContext context){final c=ref.watch(appControllerProvider),pet=c.selectedPet;final entries=pet==null?<FeedingEntry>[]:c.items('feeding_entries').map(FeedingEntry.fromMap).where((e)=>e.petId==pet.id).toList()..sort((a,b)=>b.at.compareTo(a.at));return Scaffold(appBar:AppBar(title:const Text('Feeding journal')),body:ListView(padding:const EdgeInsets.all(16),children:[TextField(controller:food,decoration:const InputDecoration(labelText:'Food brand / name *')),const SizedBox(height:10),DropdownButtonFormField<String>(value:meal,decoration:const InputDecoration(labelText:'Meal type'),items:['Meal','Treat','Water observation'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>setState(()=>meal=v!)),const SizedBox(height:10),Row(children:[Expanded(child:TextField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Amount (optional)'))),const SizedBox(width:8),DropdownButton<String>(value:unit,items:['cup','oz','g','ml','piece'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>setState(()=>unit=v!))]),const SizedBox(height:10),TextField(controller:note,decoration:const InputDecoration(labelText:'Notes')),const SizedBox(height:12),FilledButton(onPressed:add,child:const Text('Save feeding entry')),const SizedBox(height:20),const Text('History',style:TextStyle(fontSize:19,fontWeight:FontWeight.w800)),...entries.map((e)=>Card(child:ListTile(title:Text(e.food),subtitle:Text('${e.mealType} · ${DateFormat.yMMMd().add_jm().format(e.at)} · ${e.amount??'—'} ${e.unit}')))),const Text('Record only what your pet eats. Discuss diet changes or special diets with your veterinarian.') ]));}}
